-- =====================================================================
-- Catalogue Images Responsives — textes de carte, lot 1
--
-- Titre, description, cas d'usage, entree attendue et sortie annoncee.
-- Rien d'autre : ni la commande, ni la famille, ni le statut, ni l'ordre,
-- ni l'acces, ni un seul visuel. Le rapprochement verifie la commande ET
-- la famille, comme le demande le classeur : un identifiant qui aurait
-- glisse ne doit pas ecrire dans la mauvaise ligne.
-- =====================================================================

drop table if exists lot_v4;
create temporary table lot_v4 as
