.", "sortie": "1 image finale"}, {"ref": "RCI-IMG-104", "commande": "/lowpoly", "famille": "IMG-06", "nom": "Volumes polygonaux", "description": "Transformez un sujet en volumes polygonaux lisibles.", "usage": "Un projet veut une illustration géométrique simple.", "entree": "Image pour transformer un sujet précis, ou description pour une création originale.", "sortie": "1 image finale"}, {"ref": "RCI-IMG-105", "commande": "/origami", "famille": "IMG-06", "nom": "Origami", "description": "Recréez un sujet comme une sculpture de papier plié.", "usage": "Une personne veut une version origami d’un animal.", "entree": "Image pour transformer un sujet précis, ou description pour une création originale.", "sortie": "1 image finale"}, {"ref": "RCI-IMG-106", "commande": "/embroidery", "famille": "IMG-06", "nom": "Broderie textile", "description": "Recréez un motif avec des points de broderie visibles.", "usage": "Un créateur explore un motif textile.", "entree": "Image pour transformer un sujet précis, ou description pour une création originale.", "sortie": "1 image finale"}, {"ref": "RCI-IMG-107", "commande": "/woodcarve", "famille": "IMG-06", "nom": "Sculpture sur bois", "description": "Transformez un sujet en sculpture de bois.", "usage": "Un artisan veut visualiser une idée de sculpture.", "entree": "Image pour transformer un sujet précis, ou description pour une création originale.", "sortie": "1 image finale"}, {"ref": "RCI-IMG-108", "commande": "/liquidmetal", "famille": "IMG-06", "nom": "Métal liquide", "description": "Faites évoluer une zone en métal fluide et réfléchissant.", "usage": "Un projet visuel cherche un effet de matière en mouvement.", "entree": "Image pour transformer un sujet précis, ou description pour une création originale.", "sortie": "1 image finale"}, {"ref": "RCI-IMG-109", "commande": "/datamosh", "famille": "IMG-06", "nom": "Pixels étirés", "description": "Créez une image aux pixels étirés comme une vidéo corrompue.", "usage": "Un artiste prépare un visuel numérique expérimental.", "entree": "Image pour transformer un sujet précis, ou description pour une création originale.", "sortie": "1 image finale"}, {"ref": "RCI-IMG-110", "commande": "/dreamscape", "famille": "IMG-06", "nom": "Paysage onirique", "description": "Transformez une scène en paysage onirique cohérent.", "usage": "Un auteur cherche une image d’univers pour son récit.", "entree": "Image pour transformer un sujet précis, ou description pour une création originale.", "sortie": "1 image finale"}]$raccourcia$::jsonb) as d(
  ref text, commande text, famille text, nom text, description text,
  usage text, entree text, sortie text
);

do $ctrl$
declare n integer;
begin
  select count(*) into n
  from lot_v4 l
  join public.prompts p on p.external_ref = l.ref
  join public.categories c on c.id = p.category_id
  where p.command::text <> l.commande or c.external_ref <> l.famille;
  if n > 0 then
    raise exception '% lignes ne correspondent pas (commande ou famille).', n;
  end if;
end $ctrl$;

update public.prompts p
set name = l.nom,
    short_description = l.description,
    -- Un seul cas d'usage, celui qui dit quand se servir de la commande. Le
    -- second que portait la V3 recopiait la commande dans une phrase.
    use_cases = case when l.usage is null then p.use_cases else array[l.usage] end,
    expected_input = coalesce(l.entree, p.expected_input),
    expected_output = coalesce(l.sortie, p.expected_output),
    result_summary = coalesce(l.sortie, p.result_summary),
    catalog_version = 'images-responsives',
    revised_at = date '2026-09-09'
from lot_v4 l
where p.external_ref = l.ref;

drop table lot_v4;
